  const paidBy = ['CUSTOMER_EMAIL', 'CUSTOMER'].includes(policy.payment_by) ? 'customer' : 'agent'
  const [totalBill, setTotalBill] = useGetTotalBill(
    get(initialSelectedPolicy[policy.application_no], `breakup.[${paidBy}].net_payable`, 0)
  )
