import isEmpty from 'lodash/isEmpty'
import moment from 'moment'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { GENERAL_LIST_ICON } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { PolicyAdditionalInfoStyle } from './index.style'

function PolicyAdditionalInfo (props) {
  const { onClick, data } = props

  const renderInfoRow = ({
    text, value, weight,
    textSize = '12px',
    className = '',
    color = AgentColorPallette.fontDarkerGrey,
    valueColor = AgentColorPallette.fontDarkerGrey,
    onClick = () => {}
  }) => {
    return (
      <Row className={className} align='center' justify='space-between'>
        <CustomText color={color} size={textSize} weight={weight}>
          {text}
        </CustomText>
        <CustomText color={valueColor} weight={weight} onClick={onClick}>
          {value}
        </CustomText>
      </Row>
    )
  }

  return (
    <PolicyAdditionalInfoStyle>
      {
        isEmpty(data) ? (
          <Row className='cursor' align='center' justify='space-between' onClick={onClick}>
            <CustomText color={AgentColorPallette.darkerGold} weight={800}>
              {LANG_STRINGS.enterAdditionalInfo}
            </CustomText>
            <img src={GENERAL_LIST_ICON} alt='additional Icon' />
          </Row>
        ) : (
          <>
            {
              renderInfoRow({
                text: LANG_STRINGS.proofOfPayment,
                value: LANG_STRINGS.smallChange,
                textSize: '14px',
                weight: 700,
                valueColor: AgentColorPallette.darkGold,
                color: AgentColorPallette.black,
                onClick
              })
            }
            {
              renderInfoRow({
                text: LANG_STRINGS.paidTo,
                value: data.paymentPaidTo === 'FUTURA' ? LANG_STRINGS.futureMitra : LANG_STRINGS.insuranceCompany,
                className: 'paid-to'
              })
            }
            {
              renderInfoRow({
                text: LANG_STRINGS.paymentDate,
                value: moment(data.date, 'DD/MM/YYYY').format('YYYY-MM-DD')
              })
            }
          </>
        )
      }
    </PolicyAdditionalInfoStyle>
  )
}

export default PolicyAdditionalInfo
